exercise.solution:
function decodeJwt(token: string) {
  try {
    const parts = token.split(".");

    if (parts.length !== 3) {
      throw new Error("Malformed token");
    }

    const decodePart = (part: string) => {
      const base64 = part
        .replace(/-/g, "+")
        .replace(/_/g, "/");
      const padded = base64 + "=".repeat((4 - (base64.length % 4)) % 4);
      return JSON.parse(atob(padded));
    };

    return {
      header: decodePart(parts[0]),
      payload: decodePart(parts[1])
    };
  } catch {
    throw new Error("Malformed token");
  }
}

function isExpired(payload: any, nowSeconds: number): boolean {
  return typeof payload.exp !== "number" || payload.exp <= nowSeconds;
}

function hasRole(payload: any, role: string): boolean {
  return Array.isArray(payload.roles) && payload.roles.includes(role);
}
